          where: { id: commentId },
          data: { body: 'edited body', editedAt: now },
        }),
      );
      expect(result).toHaveProperty('body', 'edited body');
      expect(result).toHaveProperty('editedAt', now);
    });

    test('should only look up comments written by the current user on the article in the URL', async () => {
      // Given
      const createdAt = new Date(now.getTime() - 1 * minute);

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue({ createdAt });
      // @ts-ignore
      prismaMock.comment.update.mockResolvedValue({
        id: commentId,
        createdAt,
        updatedAt: createdAt,
        body: 'edited body',
        editedAt: now,
        author: mockedAuthor,
      });

      // Then
      await editComment('edited body', slug, commentId, userId);

      expect(prismaMock.comment.findFirst).toHaveBeenCalledWith(
        expect.objectContaining({
          where: { id: commentId, authorId: userId, article: { slug } },
        }),
      );
    });

    test('should allow the edit at exactly 30 minutes after creation', async () => {
      // Given
      const createdAt = new Date(now.getTime() - 30 * minute);

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue({ createdAt });
      // @ts-ignore
      prismaMock.comment.update.mockResolvedValue({
        id: commentId,
        createdAt,
        updatedAt: createdAt,
        body: 'edited body',
        editedAt: now,
        author: mockedAuthor,
      });

      // Then
      await expect(editComment('edited body', slug, commentId, userId)).resolves.toHaveProperty(
        'editedAt',
        now,
      );
    });

    test('should refuse the edit after the 30 minute window', async () => {
      // Given
      const createdAt = new Date(now.getTime() - 30 * minute - 1);

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue({ createdAt });

      // Then
      await expect(editComment('edited body', slug, commentId, userId)).rejects.toBeInstanceOf(
        HttpException,
      );
      expect(prismaMock.comment.update).not.toHaveBeenCalled();
    });

    test('should refuse the edit when no comment of this user matches', async () => {
      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue(null);

      // Then
      await expect(editComment('edited body', slug, commentId, userId)).rejects.toBeInstanceOf(
        HttpException,
      );
      expect(prismaMock.comment.update).not.toHaveBeenCalled();
    });

    test('should return 422 with the error body when the body is blank', async () => {
      // Then
      await expect(editComment('', slug, commentId, userId)).rejects.toMatchObject({
        errorCode: 422,
        message: { errors: { body: ["can't be blank"] } },
      });
      expect(prismaMock.comment.findFirst).not.toHaveBeenCalled();
      expect(prismaMock.comment.update).not.toHaveBeenCalled();
    });
  });
});

